package main

import (
	"bufio"
	"errors"
	"io"
	"math"
	"strconv"
)

var (
	errSyntax   = errors.New("syntax error")
	errDivZero  = errors.New("division by zero")
	errOverflow = errors.New("integer overflow")
)

// calc evaluates one expression per line, printing its value or "error".
func calc(r io.Reader, w *bufio.Writer) error {
	return forEachLine(r, func(line []byte) {
		p := parser{src: line}
		p.skipSpace()
		if p.pos == len(p.src) {
			return // blank line
		}
		v, err := p.parse()
		if err != nil {
			w.WriteString("error\n")
			return
		}
		w.WriteString(strconv.FormatInt(v, 10))
		w.WriteByte('\n')
	})
}

// parser is a recursive-descent evaluator over a single line.
type parser struct {
	src []byte
	pos int
}

func (p *parser) skipSpace() {
	for p.pos < len(p.src) && (p.src[p.pos] == ' ' || p.src[p.pos] == '\t') {
		p.pos++
	}
}

// peek returns the next non-blank byte, or 0 at end of input.
func (p *parser) peek() byte {
	p.skipSpace()
	if p.pos < len(p.src) {
		return p.src[p.pos]
	}
	return 0
}

func (p *parser) parse() (int64, error) {
	v, err := p.expr()
	if err != nil {
		return 0, err
	}
	if p.peek() != 0 {
		return 0, errSyntax
	}
	return v, nil
}

// expr := term (('+' | '-') term)*
func (p *parser) expr() (int64, error) {
	v, err := p.term()
	if err != nil {
		return 0, err
	}
	for {
		op := p.peek()
		if op != '+' && op != '-' {
			return v, nil
		}
		p.pos++
		rhs, err := p.term()
		if err != nil {
			return 0, err
		}
		if op == '+' {
			v, err = add(v, rhs)
		} else {
			v, err = sub(v, rhs)
		}
		if err != nil {
			return 0, err
		}
	}
}

// term := unary (('*' | '/' | '%') unary)*
func (p *parser) term() (int64, error) {
	v, err := p.unary()
	if err != nil {
		return 0, err
	}
	for {
		op := p.peek()
		if op != '*' && op != '/' && op != '%' {
			return v, nil
		}
		p.pos++
		rhs, err := p.unary()
		if err != nil {
			return 0, err
		}
		switch op {
		case '*':
			v, err = mul(v, rhs)
		case '/':
			v, err = div(v, rhs)
		default:
			v, err = rem(v, rhs)
		}
		if err != nil {
			return 0, err
		}
	}
}

// unary := '-' unary | primary
//
// Leading minus signs are counted iteratively so long runs cannot exhaust
// the stack; they are then applied innermost first, as the grammar implies.
func (p *parser) unary() (int64, error) {
	negations := 0
	for p.peek() == '-' {
		p.pos++
		negations++
	}
	v, err := p.primary()
	if err != nil {
		return 0, err
	}
	for range negations {
		if v, err = neg(v); err != nil {
			return 0, err
		}
	}
	return v, nil
}

// primary := NUMBER | '(' expr ')'
func (p *parser) primary() (int64, error) {
	switch c := p.peek(); {
	case c == '(':
		p.pos++
		v, err := p.expr()
		if err != nil {
			return 0, err
		}
		if p.peek() != ')' {
			return 0, errSyntax
		}
		p.pos++
		return v, nil
	case '0' <= c && c <= '9':
		return p.number()
	default:
		return 0, errSyntax
	}
}

func (p *parser) number() (int64, error) {
	var v int64
	overflow := false
	for p.pos < len(p.src) && '0' <= p.src[p.pos] && p.src[p.pos] <= '9' {
		d := int64(p.src[p.pos] - '0')
		if v > (math.MaxInt64-d)/10 {
			overflow = true
		} else {
			v = v*10 + d
		}
		p.pos++
	}
	if overflow {
		return 0, errOverflow
	}
	return v, nil
}

func add(a, b int64) (int64, error) {
	s := a + b
	if (b > 0 && s < a) || (b < 0 && s > a) {
		return 0, errOverflow
	}
	return s, nil
}

func sub(a, b int64) (int64, error) {
	d := a - b
	if (b > 0 && d > a) || (b < 0 && d < a) {
		return 0, errOverflow
	}
	return d, nil
}

func mul(a, b int64) (int64, error) {
	if a == 0 || b == 0 {
		return 0, nil
	}
	p := a * b
	if p/b != a || (a == -1 && b == math.MinInt64) || (b == -1 && a == math.MinInt64) {
		return 0, errOverflow
	}
	return p, nil
}

func div(a, b int64) (int64, error) {
	if b == 0 {
		return 0, errDivZero
	}
	if a == math.MinInt64 && b == -1 {
		return 0, errOverflow
	}
	return a / b, nil
}

func rem(a, b int64) (int64, error) {
	if b == 0 {
		return 0, errDivZero
	}
	if b == -1 {
		return 0, nil // avoids MinInt64 % -1 edge case; result is always 0
	}
	return a % b, nil
}

func neg(a int64) (int64, error) {
	if a == math.MinInt64 {
		return 0, errOverflow
	}
	return -a, nil
}

package main

import (
	"bufio"
	"bytes"
	"errors"
	"fmt"
	"io"
	"strconv"
)

const maxCapacity = 1_000_000

// nilIdx marks the absence of a neighbour in the intrusive list.
const nilIdx = -1

type lruEntry struct {
	key, value string
	prev, next int32
}

// lruCache is an LRU cache whose entries live in a slab indexed by int32,
// linked into a doubly linked list ordered from most to least recently used.
type lruCache struct {
	capacity   int
	index      map[string]int32
	entries    []lruEntry
	free       []int32
	head, tail int32 // most / least recently used
}

func newLRUCache(capacity int) *lruCache {
	return &lruCache{
		capacity: capacity,
		index:    make(map[string]int32, min(capacity, 1<<16)),
		head:     nilIdx,
		tail:     nilIdx,
	}
}

func (c *lruCache) Len() int { return len(c.index) }

func (c *lruCache) unlink(i int32) {
	e := &c.entries[i]
	if e.prev != nilIdx {
		c.entries[e.prev].next = e.next
	} else {
		c.head = e.next
	}
	if e.next != nilIdx {
		c.entries[e.next].prev = e.prev
	} else {
		c.tail = e.prev
	}
	e.prev, e.next = nilIdx, nilIdx
}

func (c *lruCache) pushFront(i int32) {
	e := &c.entries[i]
	e.prev, e.next = nilIdx, c.head
	if c.head != nilIdx {
		c.entries[c.head].prev = i
	} else {
		c.tail = i
	}
	c.head = i
}

func (c *lruCache) touch(i int32) {
	if c.head != i {
		c.unlink(i)
		c.pushFront(i)
	}
}

func (c *lruCache) remove(i int32) {
	c.unlink(i)
	delete(c.index, c.entries[i].key)
	c.entries[i] = lruEntry{prev: nilIdx, next: nilIdx}
	c.free = append(c.free, i)
}

// Get returns the value for key and marks it most recently used.
func (c *lruCache) Get(key []byte) (string, bool) {
	i, ok := c.index[string(key)]
	if !ok {
		return "", false
	}
	c.touch(i)
	return c.entries[i].value, true
}

// Set inserts or overwrites key, evicting the least recently used entry
// if the cache grows beyond its capacity.
func (c *lruCache) Set(key, value []byte) {
	if i, ok := c.index[string(key)]; ok {
		c.entries[i].value = string(value)
		c.touch(i)
		return
	}
	var i int32
	if n := len(c.free); n > 0 {
		i = c.free[n-1]
		c.free = c.free[:n-1]
	} else {
		i = int32(len(c.entries))
		c.entries = append(c.entries, lruEntry{})
	}
	k := string(key)
	c.entries[i] = lruEntry{key: k, value: string(value)}
	c.index[k] = i
	c.pushFront(i)
	if len(c.index) > c.capacity {
		c.remove(c.tail)
	}
}

// Delete removes key and reports whether it was present.
func (c *lruCache) Delete(key []byte) bool {
	i, ok := c.index[string(key)]
	if ok {
		c.remove(i)
	}
	return ok
}

// lru runs the cache simulator: a capacity line followed by commands.
func lru(r io.Reader, w *bufio.Writer) error {
	var (
		cache  *lruCache
		parseE error
	)
	err := forEachLine(r, func(line []byte) {
		if parseE != nil {
			return
		}
		if cache == nil {
			capacity, err := strconv.Atoi(string(bytes.TrimSpace(line)))
			if err != nil || capacity < 1 || capacity > maxCapacity {
				parseE = fmt.Errorf("invalid capacity %q", line)
				return
			}
			cache = newLRUCache(capacity)
			return
		}
		runLRUCommand(cache, line, w)
	})
	if err != nil {
		return err
	}
	if parseE != nil {
		return parseE
	}
	if cache == nil {
		return errors.New("missing capacity line")
	}
	return nil
}

// runLRUCommand executes one command line; malformed lines are ignored.
func runLRUCommand(c *lruCache, line []byte, w *bufio.Writer) {
	line = bytes.TrimSuffix(line, []byte{'\r'})
	op, rest, _ := bytes.Cut(line, []byte{' '})
	switch string(op) {
	case "SET":
		key, value, ok := bytes.Cut(rest, []byte{' '})
		if ok {
			c.Set(key, value)
		}
	case "GET":
		if v, ok := c.Get(rest); ok {
			w.WriteString(v)
		} else {
			w.WriteString("NULL")
		}
		w.WriteByte('\n')
	case "DEL":
		if c.Delete(rest) {
			w.WriteString("1\n")
		} else {
			w.WriteString("0\n")
		}
	case "SIZE":
		w.WriteString(strconv.Itoa(c.Len()))
		w.WriteByte('\n')
	}
}

// Command app bundles three independent stdin/stdout tools: wordfreq, lru and calc.
package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
)

const usage = "usage: app <wordfreq|lru|calc> < input"

func main() {
	if len(os.Args) != 2 {
		fmt.Fprintln(os.Stderr, usage)
		os.Exit(2)
	}

	var run func(io.Reader, *bufio.Writer) error
	switch os.Args[1] {
	case "wordfreq":
		run = wordFreq
	case "lru":
		run = lru
	case "calc":
		run = calc
	default:
		fmt.Fprintf(os.Stderr, "unknown subcommand %q\n%s\n", os.Args[1], usage)
		os.Exit(2)
	}

	out := bufio.NewWriterSize(os.Stdout, 64*1024)
	err := run(os.Stdin, out)
	if ferr := out.Flush(); err == nil {
		err = ferr
	}
	if err != nil {
		fmt.Fprintf(os.Stderr, "app %s: %v\n", os.Args[1], err)
		os.Exit(1)
	}
}

// forEachLine calls fn with every line of r, without the trailing '\n'.
// The slice passed to fn is only valid until fn returns. A final line
// lacking '\n' is still delivered; lines may be arbitrarily long.
func forEachLine(r io.Reader, fn func(line []byte)) error {
	br := bufio.NewReaderSize(r, 64*1024)
	var long []byte // accumulates lines longer than the reader's buffer
	for {
		chunk, err := br.ReadSlice('\n')
		if err == bufio.ErrBufferFull {
			long = append(long, chunk...)
			continue
		}
		line := chunk
		if len(long) > 0 {
			long = append(long, chunk...)
			line = long
		}
		if n := len(line); n > 0 {
			if line[n-1] == '\n' {
				line = line[:n-1]
			}
			fn(line)
		}
		long = long[:0]
		if err == io.EOF {
			return nil
		}
		if err != nil {
			return err
		}
	}
}

package main

import (
	"bufio"
	"cmp"
	"io"
	"strconv"
)

const topN = 10

type wordCount struct {
	word  string
	count int
}

// before reports whether a ranks ahead of b: higher count first, then
// lexicographically smaller word.
func (a wordCount) before(b wordCount) bool {
	if a.count != b.count {
		return a.count > b.count
	}
	return cmp.Less(a.word, b.word)
}

// wordFreq prints the topN most frequent case-folded ASCII-letter words of r.
func wordFreq(r io.Reader, w *bufio.Writer) error {
	counts := make(map[string]*int)
	buf := make([]byte, 256*1024)
	word := make([]byte, 0, 64) // current (possibly chunk-spanning) word, lowercased

	flush := func() {
		if len(word) == 0 {
			return
		}
		if p, ok := counts[string(word)]; ok {
			*p++
		} else {
			n := 1
			counts[string(word)] = &n
		}
		word = word[:0]
	}

	for {
		n, err := r.Read(buf)
		for _, c := range buf[:n] {
			switch {
			case 'a' <= c && c <= 'z':
				word = append(word, c)
			case 'A' <= c && c <= 'Z':
				word = append(word, c+('a'-'A'))
			default:
				flush()
			}
		}
		if err == io.EOF {
			break
		}
		if err != nil {
			return err
		}
	}
	flush()

	for _, e := range topWords(counts, topN) {
		w.WriteString(strconv.Itoa(e.count))
		w.WriteByte(' ')
		w.WriteString(e.word)
		w.WriteByte('\n')
	}
	return nil
}

// topWords returns up to n entries of counts in rank order, in O(len(counts)*n).
func topWords(counts map[string]*int, n int) []wordCount {
	top := make([]wordCount, 0, n+1)
	for word, p := range counts {
		e := wordCount{word, *p}
		if len(top) == n && !e.before(top[n-1]) {
			continue
		}
		i := len(top)
		for i > 0 && e.before(top[i-1]) {
			i--
		}
		top = append(top, wordCount{})
		copy(top[i+1:], top[i:])
		top[i] = e
		if len(top) > n {
			top = top[:n]
		}
	}
	return top
}
